            Note = { "Travel up to 2nd top floor of the tower. Whilst in `Stealth` and the Defias Tower Sentries aren't next to you, Jump onto the chair, then onto the lamp, then onto the bookshelf on top of the waypoint location", "Manually `Unstealth`, then press your \"Interact with Target\" keybind to open the Duskwood Chest. Loot it for Klaven Mortwake's Journal", "NOTE: Your `Stealth` will temporarily stop working after looting Klaven Mortwake's Journal", "Be prepared to run if you don't kill the Defias Tower Sentries on the 2nd floor. They will most likely aggro you permanently (but not attack you) when you are on top of the bookshelf as it is an evade spot", "If you have a `Dagger` in your bags or equipped, you can cast `Ambush` on the Defias Tower Patrollers and Defias Tower Sentries inside to kill them instantly. Be prepared to run after you kill the first Defias Tower Sentry and remember you can be hit from above. This is slower, but a LOT safer", "Be careful as the Malformed Defias Drone and Defias Drones can be at the entrance of the tower if you have to run out of it" },
            Range = 30,
            _index = 152,
            Class = "ROGUE",
        },
